solution.js:
describe('formatMoney', () => {
  test('formats dollars and cents', () => {
    expect(formatMoney(1234)).toBe('$12.34');
  });

  test('pads single-digit cents with a zero', () => {
    expect(formatMoney(505)).toBe('$5.05');
  });

  test('puts the minus sign before the dollar sign', () => {
    expect(formatMoney(-505)).toBe('-$5.05');
  });

  test('keeps the dollars when the cents are 50 or more', () => {
    expect(formatMoney(199)).toBe('$1.99');
  });

  test('formats zero', () => {
    expect(formatMoney(0)).toBe('$0.00');
  });
});
